import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"中孚","description":"周易正义 - 中孚","frontmatter":{"title":"中孚","description":"周易正义 - 中孚"},"headers":[],"relativePath":"zh/classics/zhengyi/061.md","filePath":"zh/classics/zhengyi/061.md"}'),l={name:"zh/classics/zhengyi/061.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>风泽中孚</p></blockquote><blockquote><p>卦辞：豚鱼吉，利涉大川，利贞。</p></blockquote><blockquote><p>彖曰：中孚，柔在内而刚得中，说而巽，孚乃化邦也。豚鱼吉，信及豚鱼也。利涉大川，乘木舟虚也。中孚以利贞，乃应乎天也。</p></blockquote><h1 id="中孚" tabindex="-1">中孚 <a class="header-anchor" href="#中孚" aria-label="Permalink to “中孚”">​</a></h1><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“中孚，豚鱼吉”者，“中孚”，卦名也。信发於中，谓之中孚。鱼者，蟲之幽隐。豚者，兽之微贱。人主内有诚信，则虽微隐之物，信皆及矣。莫不得所而获吉，故曰“豚鱼吉”也。“利涉大川，利贞”者，微隐获吉，显者可知。既有诚信，光被万物，万物得宜，以斯涉难，何往不通？故曰“利涉大川”。信而不正，凶邪之道，故利在贞也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="中孚-柔在内而刚得中-说而巽-​" tabindex="-1">中孚，柔在内而刚得中，说而巽， ​ <a class="header-anchor" href="#中孚-柔在内而刚得中-说而巽-​" aria-label="Permalink to “中孚，柔在内而刚得中，说而巽， ​”">​</a></h3><p>王弼：孚，有上四德，然后乃孚。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：此就三、四阴柔并在两体之内，二、五刚德各处一卦之中，及上下二体说而以巽，释此卦名为“中孚”之义也。柔内刚中，各当其所，说而以巽，乖争不作，所以信发於内，谓之“中孚”，故曰“柔在内而刚得中，说而巽，孚”也。</p><h3 id="乃化邦也。-​" tabindex="-1">乃化邦也。 ​ <a class="header-anchor" href="#乃化邦也。-​" aria-label="Permalink to “乃化邦也。 ​”">​</a></h3><p>王弼：信立而后邦乃化也。柔在内而刚得中，各当其所也。刚得中，则直而正；柔在内，则静而顺；说而以巽，则乖争不作。如此，则物无巧竞，敦实之行著，而笃信发乎其中矣。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：诚信发於内，则邦国化於外，故曰“乃化邦也”。</p><h3 id="豚鱼吉-信及豚鱼也。-​" tabindex="-1">“豚鱼吉”，信及豚鱼也。 ​ <a class="header-anchor" href="#豚鱼吉-信及豚鱼也。-​" aria-label="Permalink to ““豚鱼吉”，信及豚鱼也。 ​”">​</a></h3><p>王弼：鱼者，蟲之隐者也。豚者，兽之微贱者也。争竞之道不兴，中信之德淳著，则虽微隐之物，信皆及之。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：释所以得吉，由信及豚鱼故也。</p><h3 id="利涉大川-乘木舟虚也。-​" tabindex="-1">“利涉大川”，乘木舟虚也。 ​ <a class="header-anchor" href="#利涉大川-乘木舟虚也。-​" aria-label="Permalink to ““利涉大川”，乘木舟虚也。 ​”">​</a></h3><p>王弼：乘木於川舟之虚，则终已无溺也。用中孚以涉难，若乘木舟虚也。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：释此涉川所以得利，以中信而济难，若乘虚舟以涉川也。</p><h3 id="中孚以-利贞-乃应乎天也。-​" tabindex="-1">中孚以“利贞”，乃应乎天也。 ​ <a class="header-anchor" href="#中孚以-利贞-乃应乎天也。-​" aria-label="Permalink to “中孚以“利贞”，乃应乎天也。 ​”">​</a></h3><p>王弼：盛之至也。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：释中孚所以利贞者，天德刚正而气序不差，是正而信也。今信不失正，乃得应於天，是中孚之盛故须济以利贞也。</p><h2 id="《象》曰-泽上有风-中孚。君子以议狱缓死。-​" tabindex="-1">《象》曰：泽上有风，中孚。君子以议狱缓死。 ​ <a class="header-anchor" href="#《象》曰-泽上有风-中孚。君子以议狱缓死。-​" aria-label="Permalink to “《象》曰：泽上有风，中孚。君子以议狱缓死。 ​”">​</a></h2><p>王弼：信发於中，虽过可亮。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“泽上有风，中孚”者，风行泽上，无所不周，其犹信之被物，无所不至，故曰“泽上有风，中孚”。“君子以议狱缓死”者，中信之世，必非故犯过失为辜，情在可恕，故君子以议其过失之狱，缓舍当死之刑也。</p><h2 id="初九-虞吉-有它不燕。-​" tabindex="-1">初九：虞吉，有它不燕。 ​ <a class="header-anchor" href="#初九-虞吉-有它不燕。-​" aria-label="Permalink to “初九：虞吉，有它不燕。 ​”">​</a></h2><p>王弼：虞犹专也。为信之始，而应在四，得乎专吉者也，志未能变，系心於一，故“有它不燕”也。</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：虞犹专也。燕，安也。初为信始，应在于四，得其专一之吉，故曰“虞吉”。既系心於一，故更有他求，不能与之共相燕安也，故曰“有它不燕”也。</p><h3 id="《象》曰-初九-虞吉-志未变也。-​" tabindex="-1">《象》曰：“初九，虞吉”，志未变也。 ​ <a class="header-anchor" href="#《象》曰-初九-虞吉-志未变也。-​" aria-label="Permalink to “《象》曰：“初九，虞吉”，志未变也。 ​”">​</a></h3><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“志未变”者，所以得专一之吉，以志未改变，不更亲於他也。</p><h2 id="九二-鹤鸣在阴-其子和之。我有好爵-吾与尔靡之。-​" tabindex="-1">九二：鹤鸣在阴，其子和之。我有好爵，吾与尔靡之。 ​ <a class="header-anchor" href="#九二-鹤鸣在阴-其子和之。我有好爵-吾与尔靡之。-​" aria-label="Permalink to “九二：鹤鸣在阴，其子和之。我有好爵，吾与尔靡之。 ​”">​</a></h2><p>王弼：处内而居重阴之下，而履不失中，不徇於外，任其真者也。立诚笃至，虽在闇昧，物亦应焉，故曰“鸣鹤在阴，其子和之”也。不私权利，唯德是与，诚之至也，故曰我有好爵，与物散之。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“鸣鹤在阴，其子和之”者，九二体刚，处於卦内，又在三四重阴之下，而履不失中，是不徇於外，自任其真者也。处於幽昧，而行不失信，则声闻于外，为同类之所应焉。如鹤之鸣於幽远，则为其子所和，故曰“鸣鹤在阴，其子和之”也。“我有好爵，吾与尔靡之”者，靡，散也，又无偏应，是不私权利，惟德是与。若我有好爵，吾原与尔贤者分散而共之，故曰“我有好爵，吾与尔靡之。”</p><h3 id="《象》曰-其子和之-中心愿也。-​" tabindex="-1">《象》曰：“其子和之”，中心愿也。 ​ <a class="header-anchor" href="#《象》曰-其子和之-中心愿也。-​" aria-label="Permalink to “《象》曰：“其子和之”，中心愿也。 ​”">​</a></h3><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“中心愿”者，诚信之人，愿与同类相应，得诚信而应之，是中心愿也。</p><h2 id="六三-得敌-或鼓或罢-或泣或歌。-​" tabindex="-1">六三：得敌，或鼓或罢，或泣或歌。 ​ <a class="header-anchor" href="#六三-得敌-或鼓或罢-或泣或歌。-​" aria-label="Permalink to “六三：得敌，或鼓或罢，或泣或歌。 ​”">​</a></h2><p>王弼：三居少阴之上，四居长阴之下，对而不相比，敌之谓也。以阴居阳，欲进者也。欲进而阂敌，故或鼓也。四履正而承五，非己所克，故或罢也。不胜而退，惧见侵陵，故或泣而忧悲也。四履于顺。不与物校，退而不见害，故或歌也。不量其力，进退无恒，惫可知也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：六三与四，俱是阴爻，相与为类。然三居少阴之桑四居长阴之下，各自有应对，而不相比，敌之谓也。故曰“得敌欲进”。碍四，恐其害己，故或鼓而攻之，而四履正承尊，非己所胜，故或罢而退败也。不胜而退，惧见侵陵，故或泣而忧悲也。四履于顺，不与物校，退不见害，故或歌而欢乐也，故曰“或鼓或罢，或泣或歌”也。</p><h3 id="《象》曰-或鼓或罢-位不当也。-​" tabindex="-1">《象》曰：“或鼓或罢”，位不当也。 ​ <a class="header-anchor" href="#《象》曰-或鼓或罢-位不当也。-​" aria-label="Permalink to “《象》曰：“或鼓或罢”，位不当也。 ​”">​</a></h3><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“位不当”者，所以或鼓或罢，进退无恒者，止为不当其位，妄进故也。</p><h2 id="六四-月几望-马匹亡-无咎。-​" tabindex="-1">六四：月几望，马匹亡，无咎。 ​ <a class="header-anchor" href="#六四-月几望-马匹亡-无咎。-​" aria-label="Permalink to “六四：月几望，马匹亡，无咎。 ​”">​</a></h2><p>王弼：居中孚之时，处巽之始，应说之初，居正履顺，以承於五，内毗无首，外宣德化者也。充乎阴德之盛，故曰：“月几望”。“马匹亡”者，弃群类也。若夫居盛德之位，而与物校其竞争，则失其所盛矣，故曰绝类而上，履正承尊，不与三争，乃得无咎也。</p><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“月几望”者，六四居中孚之时，处巽应说，得位履顺，上承於五，内毗元首，外宣德化，充乎阴德之盛，如月之近望，故曰“月几望”也。“马匹亡，无咎”者，三与己敌，进来攻己，己若与三校战，则失其所盛，故弃三之类，如马之亡匹；上承其五，不与三争，乃得无咎，故曰“马匹亡，无咎”也。</p><h3 id="《象》曰-马匹亡-绝类上也。-​" tabindex="-1">《象》曰：“马匹亡”，绝类上也。 ​ <a class="header-anchor" href="#《象》曰-马匹亡-绝类上也。-​" aria-label="Permalink to “《象》曰：“马匹亡”，绝类上也。 ​”">​</a></h3><p>王弼：类谓三，俱阴爻，故曰“类”也。</p><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“绝类上”者，绝三之类，不与二争，而上承於五也。</p><h2 id="九五-有孚挛如-无咎。-​" tabindex="-1">九五：有孚挛如，无咎。 ​ <a class="header-anchor" href="#九五-有孚挛如-无咎。-​" aria-label="Permalink to “九五：有孚挛如，无咎。 ​”">​</a></h2><p>王弼：“挛如”者，系其信之辞也。处中诚以相交之时，居尊位以为群物之主，信何可舍？故“有孚挛如”，乃得“无咎”也。</p><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“有孚挛如，无咎”者，挛如者，相牵系不绝之名也。五在信时，处於尊位，为群物之主，恒须以中诚交物，孚信何可暂舍，故曰“有孚挛如”。系信不绝，乃得无咎，故曰“有孚挛如，无咎”也。</p><h3 id="《象》曰-有孚挛如-位正当也。-​" tabindex="-1">《象》曰：“有孚挛如”，位正当也。 ​ <a class="header-anchor" href="#《象》曰-有孚挛如-位正当也。-​" aria-label="Permalink to “《象》曰：“有孚挛如”，位正当也。 ​”">​</a></h3><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“位正当”者，以其正当尊位，故戒以系信，乃得无咎。若真以阳得正位，而无有系信，则招有咎之嫌也。</p><h2 id="上九-翰音登于天-贞凶。-​" tabindex="-1">上九：翰音登于天，贞凶。 ​ <a class="header-anchor" href="#上九-翰音登于天-贞凶。-​" aria-label="Permalink to “上九：翰音登于天，贞凶。 ​”">​</a></h2><p>王弼：翰，高飞也。飞音者，音飞而实不从之谓也。居卦之上，处信之终，信终则衰，忠笃内丧，华美外扬，故曰“翰音登于天”也。翰音登天，正亦灭矣。</p><h3 id="疏-17" tabindex="-1">疏 <a class="header-anchor" href="#疏-17" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：翰，高飞也。飞音者，音飞而实不从之谓也。上九处信之终信终则衰也。信衰则诈起，而忠笃内丧，华美外扬，若鸟於翰音登于天，虚声远闻也，故曰“翰音登于天”。虚声无实，正之凶也，故曰“贞凶”。</p><h3 id="《象》曰-翰音登于天-何可长也。-​" tabindex="-1">《象》曰：“翰音登于天”，何可长也。 ​ <a class="header-anchor" href="#《象》曰-翰音登于天-何可长也。-​" aria-label="Permalink to “《象》曰：“翰音登于天”，何可长也。 ​”">​</a></h3><h3 id="疏-18" tabindex="-1">疏 <a class="header-anchor" href="#疏-18" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“何可长也”者，虚声无实，何可久长。</p>',74)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
